package next.probes

fun floatLt(a: Float, b: Float): Boolean = a < b
fun floatLe(a: Float, b: Float): Boolean = a <= b
fun floatGt(a: Float, b: Float): Boolean = a > b
fun floatGe(a: Float, b: Float): Boolean = a >= b
fun floatEq(a: Float, b: Float): Boolean = a == b
fun floatNe(a: Float, b: Float): Boolean = a != b
fun nullableFloatEq(a: Float?, b: Float?): Boolean = a == b
